       double mae=0,maxerr=0;long long den=variant?tot_in[rj]:tot_ex[rj];
       for(auto &g:genes){
         double x=query[g][oi];long long s=variant?sums[g].in[rj]:sums[g].ex[rj];double y=den?100000.0*s/den:0;
         a.push_back(x);b.push_back(y);al.push_back(log1p(x));bl.push_back(log1p(y));double e=abs(x-y);mae+=e;maxerr=max(maxerr,e);
       }
       double cr=cor(a,b),cl=cor(al,bl);mae/=genes.size();ranking.push_back({cl,rj});
       out<<"correlation_log1p\t"<<vn<<"\t"<<labels[oi]<<"\t"<<labels[rj]<<"\t"<<setprecision(10)<<cl<<"\traw_cor="<<cr<<";mae_cpm="<<mae<<";maxerr="<<maxerr<<"\n";
     }
     sort(ranking.rbegin(),ranking.rend());
     out<<"best_match\t"<<vn<<"\t"<<labels[oi]<<"\t"<<labels[ranking[0].second]<<"\t"<<ranking[0].first<<"\tsecond="<<labels[ranking[1].second]<<":"<<ranking[1].first<<"\n";
   }
 }
